$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies System.Drawing -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
public class NinjaRun53 {
 public static int[] Sole(Bitmap b){int ground=0,left=b.Width,right=0;for(int y=b.Height/2;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>128)ground=Math.Max(ground,y);for(int y=ground-4;y<=ground;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>128){left=Math.Min(left,x);right=Math.Max(right,x);}return new[]{left,right,ground};}
 public static int HoodTop(Bitmap b,double[] roi){int top=b.Height;for(int y=(int)(b.Height*roi[1]);y<b.Height*(roi[1]+roi[3]);y++)for(int x=(int)(b.Width*roi[0]);x<b.Width*(roi[0]+roi[2]);x++){var c=b.GetPixel(x,y);if(c.A>128&&c.R<80&&c.G<80&&c.B<100)top=Math.Min(top,y);}return top;}
 public static Bitmap Place(Bitmap b,double scale,double tx,double ty){var dst=new Bitmap(384,320,System.Drawing.Imaging.PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(dst)){g.Clear(Color.Transparent);g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(b,new RectangleF((float)tx,(float)ty,(float)(b.Width*scale),(float)(b.Height*scale)),new RectangleF(0,0,b.Width,b.Height),GraphicsUnit.Pixel);}return dst;}
 public static int[] Components(Bitmap b){var seen=new bool[b.Width,b.Height];var sizes=new List<int>();for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){if(seen[x,y]||b.GetPixel(x,y).A<64)continue;int count=0;var q=new Queue<int>();q.Enqueue(y*b.Width+x);seen[x,y]=true;while(q.Count>0){var v=q.Dequeue();int vx=v%b.Width,vy=v/b.Width;count++;for(int yy=Math.Max(0,vy-1);yy<=Math.Min(b.Height-1,vy+1);yy++)for(int xx=Math.Max(0,vx-1);xx<=Math.Min(b.Width-1,vx+1);xx++)if(!seen[xx,yy]&&b.GetPixel(xx,yy).A>=64){seen[xx,yy]=true;q.Enqueue(yy*b.Width+xx);}}sizes.Add(count);}sizes.Sort();sizes.Reverse();return sizes.ToArray();}
}
'@

$repo=Split-Path $PSScriptRoot -Parent;$source=Join-Path $repo 'integration/ninja-run-combat-reference';$plan=Get-Content -LiteralPath (Join-Path $source 'plan.json') -Raw -Encoding UTF8|ConvertFrom-Json
if((Get-FileHash -LiteralPath (Join-Path $repo $plan.source) -Algorithm SHA256).Hash.ToLower() -ne $plan.sourceSha256){throw 'Artwork source changed; update source landmarks first'}
$out=Join-Path $repo $plan.reviewDirectory;New-Item -ItemType Directory -Force $out|Out-Null;$dir=Join-Path $out 'motion-frames';New-Item -ItemType Directory -Force $dir|Out-Null
$art=[System.Drawing.Bitmap]::new((Join-Path $repo $plan.source));$old=[System.Drawing.Bitmap]::new((Join-Path $repo $plan.oldRunReference));$combat=[System.Drawing.Bitmap]::new((Join-Path $repo $plan.referenceCombat));$combatMeta=Get-Content -LiteralPath (Join-Path $repo $plan.referenceCombatMetadata) -Raw -Encoding UTF8|ConvertFrom-Json;$contract=Get-Content -LiteralPath (Join-Path $repo $plan.referenceContract) -Raw -Encoding UTF8|ConvertFrom-Json;$measure=Get-Content -LiteralPath (Join-Path $repo $plan.measurements) -Raw -Encoding UTF8|ConvertFrom-Json
$controlRect=[int[]]$measure[$plan.controlCell].sourceRect;$control=$art.Clone([System.Drawing.Rectangle]::new($controlRect[0],$controlRect[1],$controlRect[2],$controlRect[3]),[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$hood=[NinjaRun53]::HoodTop($control,[double[]]$plan.controlHoodRegion);$controlSole=[NinjaRun53]::Sole($control);$scale=$plan.bodyControlHeight/($controlSole[2]-$hood);$dy=$plan.targetGround-$measure[$plan.contactSourceCell].floor*$scale
$calibration=[NinjaRun53]::Place($control,$scale,(192.5-($controlSole[0]+$controlSole[1])*.5*$scale),(289-$controlSole[2]*$scale));$calibration.Save((Join-Path $out 'source-calibration.png'));$calibration.Dispose()
$atlas=[System.Drawing.Bitmap]::new(2304,640,[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$frames=@();$observations=@();$font=[System.Drawing.Font]::new('Arial',14)
for($i=0;$i -lt 12;$i++){$slot=[int]$plan.selectedCells[$i];$m=$measure[$slot];$r=[int[]]$m.sourceRect;$cell=$art.Clone([System.Drawing.Rectangle]::new($r[0],$r[1],$r[2],$r[3]),[System.Drawing.Imaging.PixelFormat]::Format32bppArgb);$dx=$plan.pelvisTargetX-$m.beltAnchor[0]*$scale;$pose=[NinjaRun53]::Place($cell,$scale,$dx,$dy);$x=($i%6)*384;$y=[int][Math]::Floor($i/6)*320;$g=[System.Drawing.Graphics]::FromImage($atlas);$g.CompositingMode=[System.Drawing.Drawing2D.CompositingMode]::SourceCopy;$g.DrawImageUnscaled($pose,$x,$y);$g.Dispose();$pose.Save((Join-Path $dir ('pose-'+$i+'.png')));$sole=[NinjaRun53]::Sole($pose);$components=[NinjaRun53]::Components($pose);$observations+=@{frame=$i;sourceCell=$slot;sourceRect=$r;sourceWaist=$m.beltAnchor;translation=@($dx,$dy);worldFootLowestY=$sole[2];footGapToPlane=(289-$sole[2]);detachedComponentsOver3Pixels=[Math]::Max(0,@($components|Where-Object {$_ -gt 3}).Count-1);alphaAtTopLeft=$pose.GetPixel(0,0).A};$frames+=@{x=$x;y=$y;width=384;height=320;sourceWidth=384;sourceHeight=320;offsetX=0;offsetY=0;pivot=$plan.pivot;label=$plan.frameLabels[$i];sourceCell=$slot};$cell.Dispose();$pose.Dispose()}
$atlas.Save((Join-Path $out 'run-atlas.png'));Copy-Item -LiteralPath (Join-Path $repo $plan.referenceCombat) -Destination (Join-Path $out 'combat51-atlas.png');Copy-Item -LiteralPath (Join-Path $repo $plan.oldRunReference) -Destination (Join-Path $out 'old-run-reference.png')
$light=[System.Drawing.Bitmap]::new(2304,640);$lg=[System.Drawing.Graphics]::FromImage($light);$lg.Clear([System.Drawing.Color]::FromArgb(222,230,240));$lg.DrawImageUnscaled($atlas,0,0);$lg.Dispose();$light.Save((Join-Path $out 'contact-sheet-light.png'));$light.Dispose()
for($i=0;$i -lt 12;$i++){$ms=$i*1000.0/$plan.fps;$bi=[int][Math]::Floor($ms/140)%6;$oi=[int][Math]::Floor($ms*$contract.existingRun.clip.fps/1000)%8;$rf=$combatMeta.clips.combatIdle.frames[$bi];$nx=$frames[$i].x;$ny=$frames[$i].y;$b=[System.Drawing.Bitmap]::new(1152,880);$g=[System.Drawing.Graphics]::FromImage($b);$g.Clear([System.Drawing.Color]::FromArgb(20,35,55));$g.InterpolationMode=[System.Drawing.Drawing2D.InterpolationMode]::NearestNeighbor;$images=@($combat,$old,$atlas);$rects=@([System.Drawing.Rectangle]::new($rf.x,$rf.y,384,320),[System.Drawing.Rectangle]::new((($oi%4)*384),([int][Math]::Floor($oi/4)*320),384,320),[System.Drawing.Rectangle]::new($nx,$ny,384,320));$labels=@('APPROVED51 - SCALE','CURRENT RUN -8FRAMES','NEW RUN -12FRAMES');for($c=0;$c -lt 3;$c++){$g.DrawString($labels[$c],$font,[System.Drawing.Brushes]::Wheat,($c*384+10),10);$g.DrawImage($images[$c],[System.Drawing.Rectangle]::new(($c*384),55,384,320),$rects[$c],[System.Drawing.GraphicsUnit]::Pixel);$g.DrawLine([System.Drawing.Pens]::SlateGray,($c*384+20),344,($c*384+364),344);$g.DrawImage($images[$c],[System.Drawing.Rectangle]::new(($c*384+12),420,360,360),[System.Drawing.Rectangle]::new(($rects[$c].X+55),($rects[$c].Y+20),280,280),[System.Drawing.GraphicsUnit]::Pixel)};$g.DrawString(('FRAME '+($i+1)+'/12 - '+$plan.frameLabels[$i]),$font,[System.Drawing.Brushes]::Wheat,10,830);$g.Dispose();$b.Save((Join-Path $dir ('frame-'+$i+'.png')));$b.Save((Join-Path $dir ('frame-'+$i+'.gif')),[System.Drawing.Imaging.ImageFormat]::Gif);$b.Dispose()}
$data=@{status=$plan.status;image='run-atlas.png';frameWidth=384;frameHeight=320;columns=6;frames=$frames;fps=$plan.fps;loop=$true;pivot=$plan.pivot;control=@{sourceCell=0;hoodTop=$hood;ground=$controlSole[2];sharedScale=$scale;sharedVerticalTranslation=$dy;method=$plan.normalization};reference=@{combatIdleFrames=$combatMeta.clips.combatIdle.frames;combatFps=$combatMeta.clips.combatIdle.fps;oldRunFps=$contract.existingRun.clip.fps};observations=$observations;productionChanged=$false;runtimeChanged=$false}
[System.IO.File]::WriteAllText((Join-Path $out 'review.json'),($data|ConvertTo-Json -Depth 12),[System.Text.UTF8Encoding]::new($false));[System.IO.File]::WriteAllText((Join-Path $out 'review-data.js'),('window.ninjaRun='+($data|ConvertTo-Json -Depth 12 -Compress)+';'),[System.Text.UTF8Encoding]::new($false));foreach($file in @('preview.html','preview.js')){Copy-Item -LiteralPath (Join-Path $source $file) -Destination (Join-Path $out $file)}
& node (Join-Path $repo 'scripts/assemble_ninja_run_reference_review.mjs');if($LASTEXITCODE -ne 0){throw 'GIF assembly failed'}
$paths=@('integration/ninja-run-combat-reference/plan.json',$plan.source,'integration/ninja-run-combat-reference/run-source.png','integration/ninja-run-combat-reference/run-loop-source.png','integration/ninja-run-combat-reference/run-arm-prompt.txt','integration/ninja-run-combat-reference/run-prompt.txt','integration/ninja-run-combat-reference/run-closure-prompt.txt',$plan.measurements,$plan.referenceCombat,$plan.referenceLocomotion,$plan.referenceCombatMetadata,$plan.referenceContract,'scripts/prepare_ninja_run_combat_reference.ps1',($plan.reviewDirectory+'/run-atlas.png'));$hashes=foreach($p in $paths){@{path=$p;sha256=(Get-FileHash -LiteralPath (Join-Path $repo $p) -Algorithm SHA256).Hash.ToLower()}};[System.IO.File]::WriteAllText((Join-Path $out 'provenance.json'),(@{status=$plan.status;files=$hashes;method=$plan.normalization}|ConvertTo-Json -Depth 10),[System.Text.UTF8Encoding]::new($false));$atlas.Dispose();$art.Dispose();$old.Dispose();$combat.Dispose();$control.Dispose();$font.Dispose();Write-Output (@{control=$data.control;observations=$observations}|ConvertTo-Json -Depth 12 -Compress)
